\label{lem:polar-continuation}
For every sufficiently small $t_0=j_0^{-1/3}$, the data in
\eqref{eq:polar-initial-matrix}--\eqref{eq:polar-matrix-map} define an
infinite matrix sequence. For all $j\ge0$,
\begin{equation}\label{eq:polar-tube-estimates}
\begin{aligned}
 A_j&=K_*+O(t_j),\\
 (C_j,V_j)-(A_jw(\nu(A_j)),1+A_jw(\nu(A_j))^2)&=O(t_j^3).
\end{aligned}
\end{equation}
Every matrix $Z_k$ is positive definite, and
$(Z_k)_{12}>0$, $W_k>0$, and $\sigma_k>0$.
The constants are independent of $j_0$ once $t_0$ is below a fixed threshold.

\label{lem:polar-geometry}
The polar points satisfy, with $j=\lfloor k/2\rfloor$,
\begin{equation}\label{eq:polar-orders}
 r_k-1=3(D_0+D_1)t_j+O(t_j^2),\quad
 r_k-r_{k+1}\asymp t_j^4,\quad
 \|x_{k+1}-x_k\|\asymp t_j^2.
\end{equation}
Their accumulation set is $\Gamma=\{x\in\R^2:\|x\|=1\}$, and a
constant $c>0$, independent of $j_0$, satisfies
\begin{equation}\label{eq:polar-separation}
 \|x_m-x_k\|\ge c\max\{t_{\lfloor k/2\rfloor}^2,
                              t_{\lfloor m/2\rfloor}^2\}
 \qquad(m\ne k).
\end{equation}

\label{lem:polar-interpolation}
Each $\psi_k$ is smooth, and its Hessian is globally $1/2$-H\"older
continuous with constant at most $C_\chi\|a_k\|\rho_k^{-3/2}$,
where $C_\chi$ depends only on $\chi$.
The function $\Psi$ in \eqref{eq:polar-objective} belongs to
$C^2(\mathbb R^2)$ and has a globally $1/2$-H\"older continuous Hessian.
Its value, gradient, and Hessian vanish on $\Gamma$, and
\begin{equation}\label{eq:polar-interpolation-jets}
\Psi(x_k)=0,\qquad \nabla\Psi(x_k)=a_k,\qquad
\nabla^2\Psi(x_k)=0.
\end{equation}
There is a constant $C$, independent of the final choice of $j_0$, such that
\begin{equation}\label{eq:polar-interpolation-bound}
\sup_{x\in\mathbb R^2}\|\nabla^2\Psi(x)\|\le Ct_0.
\end{equation}

\label{cm-center-proposition}
The derivative of $\mathcal F$ at $(0,2,1)$ has eigenvalues
$1,-1/9,0$. The map has a locally invariant $C^7$ graph
$p=p(\epsilon)$, $h=h(\epsilon)$ satisfying
\begin{equation}\label{cm-center-expansions}
 \begin{aligned}
 p(\epsilon)&=2+\frac{198}{5}\epsilon^3+O(\epsilon^4),&
 h(\epsilon)&=1+8\epsilon^3+O(\epsilon^4),\\
 \epsilon_+&=\epsilon-\frac32\epsilon^4+O(\epsilon^5).
 \end{aligned}
\end{equation}
For every sufficiently small $\widehat\epsilon_0>0$, the initial data
\begin{equation}\label{cm-initial-data}
 \widehat x_0=\widehat g_0=
 \binom{1}{p(\widehat\epsilon_0)\widehat\epsilon_0^2},\qquad
 \widehat H_0=
 \begin{pmatrix}
 h(\widehat\epsilon_0)p(\widehat\epsilon_0)\widehat\epsilon_0^4&0\\
 0&h(\widehat\epsilon_0)
 \end{pmatrix}
\end{equation}
generate an infinite secant recurrence by
\eqref{cm-single-step}--\eqref{cm-alternating-data} and
$\widehat x_{k+1}=\widehat x_k+\widehat s_k$.
Every $\widehat H_k$ is positive definite. At the start of cycle $j$,
the spectral coordinates satisfy
$\widehat p_j=p(\widehat\epsilon_j)$,
$\widehat h_j=h(\widehat\epsilon_j)$,
$\widehat r_j=\widehat\epsilon_j^2$, and
\begin{equation}\label{cm-scale-asymptotic}
 \widehat\epsilon_j\sim\left(\frac92j\right)^{-1/3}.
\end{equation}
